import React from "react";
import SinglePost from "./singelPostComponent";

class Home extends React.Component {

    constructor(props){
        super(props);

        this.state = {
            loading: 'a'
        };
    }

    componentDidMount() {
        console.log('Home Mounted');

        fetch("/api/")  // ← این را با URL واقعی API جایگزین کن
            .then(res => {
                this.setState({
                    loading: 'a'
                });
            })
            .then(res => {
                this.setState({
                    loading: res.status
                });
            })
            .catch(err => {
                this.setState({
                    loading: 'res.status'
                });
            });
    }

    render() {


        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

{this.state.loading}

                </div>
            </main>
        );
    }
}

export default Home;
